const API_KEY = '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';

interface CodeReviewResponse {
  review: string;
  score: number;
  suggestions: string[];
}

export const reviewCode = async (code: string, taskDescription: string): Promise<CodeReviewResponse> => {
  try {
    const response = await fetch('https://api.skynet.com/v1/code-review', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${API_KEY}`
      },
      body: JSON.stringify({
        code,
        taskDescription,
        language: 'javascript' // или другой язык, который использует пользователь
      })
    });

    if (!response.ok) {
      throw new Error('Ошибка при проверке кода');
    }

    return await response.json();
  } catch (error) {
    console.error('Ошибка при отправке кода на проверку:', error);
    throw error;
  }
};
